      // popup-side per frame, so this line is actually observable.
      if (_sanQ.length !== _sanIn.length) {
        _lpD('[LP QUOTE-STRIP DIAG] newline-anchored "> quoted" block removed — ' + (_sanIn.length - _sanQ.length) + ' chars');
      }
