    var lastSubstantiveOutboundMsg = '';     // (v9.7.269) most-recent NON-trivial outbound (second-touch extraction #2)
    var lastSubstantiveOutboundMs = 0;       // (v9.7.271) timestamp of the most-recent SUBSTANTIVE outbound
