        var anDays = Math.round(anAge / (1000*60*60*24));
        var anLabel = anDays === 0 ? 'today' : anDays === 1 ? 'yesterday' : anDays + ' days ago';

        var isApptRelated = false;
        var apptEvent = '';

        // v9.7.206 — Appointment CANCELLATION detection. Catches both the agent
