          // merge erases the evidence and the next distance incident has to be reasoned backwards
          // from the delivered prompt again.
          try {
            var _adRows = sorted.map(function(fr){
              var r = (fr && fr.result) || {};
              return { lead: r.autoLeadId || null, cust: r.customerId || null,
                       st: r.customerState || '', zip: r.customerZip || '' };
            });
            var _adDistinct = {};
            _adRows.forEach(function(r){ if (r.st || r.zip) _adDistinct[r.st + '|' + r.zip] = 1; });
            var _adKeys = Object.keys(_adDistinct);
            console.log('[LP ADDRESS DIAG] perFrame:' + JSON.stringify(_adRows)
              + ' | distinctAddresses:' + _adKeys.length
              + ' | activeCustomerId:' + (_activeCustomerId || '(none)')
              + ' | pass1HadActiveFrame:' + _pass1HadActiveFrame
              + ' | merged:' + (m.customerState || '(none)') + '/' + (m.customerZip || '(none)'));
            if (_adKeys.length > 1) {
              console.warn('[LP ADDRESS DIAG] FRAMES DISAGREE on the customer address — ' + JSON.stringify(_adKeys)
                + '. The merged value above is what the distance system will use. If it is not this'
                + ' customer\'s real address, this line names the frame that supplied it.');
            }
          } catch (_eAd) {}
